 import { MeshPhysicalNodeMaterial } from 'three/webgpu';
import { texture, uv, vec3, float, positionLocal, add, mul } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, BoxGeometry, Color } = THREE;

  const group = new Group();
  group.name = config.id || 'features-list-row';

  const colors = config.intent?.visualSpec?.colors || {};
  const palette = {
    ink: new Color(colors.ink ?? '#16161d'),
    paper: new Color(colors.paper ?? '#e8ecf2'),
    accent: new Color(colors.accent ?? '#ff2a38'),
    surface: new Color(colors.surface ?? '#0b0b10'),
  };

  const width = 2.4;
  const height = 1.5;
  const cardDepth = 0.08;

  const frameGeo = new BoxGeometry(width + 0.12, height + 0.12, cardDepth);
  const frameMat = new MeshPhysicalNodeMaterial({
    color: palette.surface,
    roughness: 0.7,
    metalness: 0.3,
    clearcoat: 0.12,
    emissive: palette.accent,
    emissiveIntensity: 0,
  });
  const frame = new Mesh(frameGeo, frameMat);
  frame.position.z = -0.05;
  group.add(frame);

  const planeGeo = new PlaneGeometry(width, height, 64, 64);
  const planeMat = new MeshPhysicalNodeMaterial({
    color: 0xffffff,
    roughness: 0.6,
    metalness: 0.1,
    clearcoat: 0.05,
  });
  const plane = new Mesh(planeGeo, planeMat);
  group.add(plane);

  let imageTex = null;
  let depthTex = null;

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      imageTex = tex;
      imageTex.colorSpace = THREE.SRGBColorSpace;
      planeMat.map = imageTex;
      planeMat.needsUpdate = true;
    });
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      depthTex = tex;
      depthTex.colorSpace = THREE.NoColorSpace;
      const displacement = mul(texture(depthTex, uv()).r, float(0.25));
      planeMat.positionNode = add(positionLocal, vec3(0.0, 0.0, displacement));
      planeMat.needsUpdate = true;
    });
  }

  const parallax = ctx.primitives['parallax-scroll'](group, { strength: 0.05, damping: 0.08 });

  group.userData.handlers = {
    hover: (e) => {
      const over = !(e && e.isHovered === false);
      gsap.killTweensOf(group.position);
      gsap.killTweensOf(group.scale);
      gsap.killTweensOf(frameMat);
      if (over) {
        gsap.to(group.position, { z: '+=0.15', duration: 0.35, ease: 'power2.out' });
        gsap.to(group.scale, { x: 1.02, y: 1.02, z: 1.02, duration: 0.35, ease: 'power2.out' });
        gsap.to(frameMat, { emissiveIntensity: 0.55, duration: 0.35, ease: 'power2.out' });
      } else {
        gsap.to(group.position, { z: '-=0.15', duration: 0.45, ease: 'power2.out' });
        gsap.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.45, ease: 'power2.out' });
        gsap.to(frameMat, { emissiveIntensity: 0, duration: 0.45, ease: 'power2.out' });
      }
    },
    click: () => {
      gsap.to(group.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(1.7)',
        yoyo: true,
        repeat: 1,
      });
      ctx.emit('hub-features.select', {});
    },
  };

  group.userData.cleanup = () => {
    parallax?.cleanup?.();
    gsap.killTweensOf(group.position);
    gsap.killTweensOf(group.scale);
    gsap.killTweensOf(frameMat);
    frameGeo.dispose();
    planeGeo.dispose();
    frameMat.dispose();
    planeMat.dispose();
    if (imageTex) imageTex.dispose();
    if (depthTex) depthTex.dispose();
  };

  return group;
}
